<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute } from 'vue-router'
import { ArrowLeft, FileText, CalendarDays, Save, Send, CheckCircle2, LockKeyhole, Pencil, Eye, RefreshCw, X, History, Users } from '@lucide/vue'
import {setCourseExperience} from '../composables/experience'
import { api } from '../api'
import { experience } from '../composables/experience'
import { auth } from '../composables/auth'
import QuestionAnswer from '../components/QuestionAnswer.vue'
import DiscussionPanel from '../components/DiscussionPanel.vue'
import TeachingPanel from '../components/TeachingPanel.vue'
import AssignmentEditor from '../components/AssignmentEditor.vue'
import QuizScoringPlan from '../components/QuizScoringPlan.vue'
import { assignmentStatus, submissionStatus, formatDate } from '../utils/assignments'
const route = useRoute(), assignment = ref(null), own = ref(null), answers = ref({}), submitted = ref([]), review = ref(null)
const loading = ref(true), busy = ref(false), editing = ref(false), error = ref(''), notice = ref(''), now = ref(Date.now())
const timer = setInterval(() => { now.value = Date.now() }, 15000)
const staff = computed(() => ['teacher', 'ta'].includes(assignment.value?.courseRole))
const dirty = computed(() => own.value && (own.value.status !== 'submitted' || assignment.value?.allowRevisions) && own.value.answers.some(answer => (answers.value[answer.questionId] || '') !== answer.text))
const canWrite = computed(() => assignment.value?.courseRole === 'student' && assignment.value.status === 'published' && assignment.value.courseStatus !== 'archived' && (own.value?.status !== 'submitted' || assignment.value.allowRevisions) && !assignment.value.learningGate?.locked && own.value?.status !== 'withdrawn' && (!assignment.value.opensAt || now.value >= Date.parse(assignment.value.opensAt)) && (!assignment.value.dueAt || now.value < Date.parse(assignment.value.dueAt)))
const restriction = computed(() => {
  if (own.value?.status === 'submitted' && !assignment.value?.allowRevisions) return `已於 ${formatDate(own.value.submittedAt)} 提交。此份作答已鎖定，以下為提交紀錄。`
  if (assignment.value?.status === 'closed') return '測驗已由教師關閉；已儲存的內容仍可檢視。'
  if (assignment.value?.courseStatus === 'archived') return '課程已封存，目前無法繼續作答。'
  if (assignment.value?.opensAt && now.value < Date.parse(assignment.value.opensAt)) return '尚未到開放作答時間。'
  if (assignment.value?.dueAt && now.value >= Date.parse(assignment.value.dueAt)) return '已超過截止時間，目前無法儲存或提交。'
  return ''
})
function acceptSubmission(value) { own.value = value; answers.value = Object.fromEntries(value.answers.map(a => [a.questionId, a.text])) }
async function load() {
  loading.value = true; error.value = ''; notice.value = ''; review.value = null; editing.value = false
  try { assignment.value = await api(`/assignments/${route.params.assignmentId}`);setCourseExperience(['teacher','ta'].includes(assignment.value.courseRole)||assignment.value.isPractice); if(route.meta?.quiz && !assignment.value.isQuiz){assignment.value=null;throw new Error("找不到此線上測驗。")} if (staff.value) submitted.value = await api(`/assignments/${assignment.value.id}/submissions`); else acceptSubmission(await api(`/assignments/${assignment.value.id}/my-submission`)) } catch (e) { error.value = e.message } finally { loading.value = false }
}
onMounted(load)
async function reload() { if (dirty.value && !window.confirm('重新載入會放棄此頁尚未儲存的修改，確定繼續？')) return; await load() }
async function saveAssignment(payload) { busy.value = true; error.value = ''; try { assignment.value = await api(`/assignments/${assignment.value.id}`, { method: 'PUT', body: payload }); editing.value = false; notice.value = '測驗草稿已儲存。' } catch (e) { error.value = e.message } finally { busy.value = false } }
async function transition(target) {
  if (!window.confirm(target === 'publish' ? '發布後學生即可查看測驗，題目與說明將鎖定。確定發布？' : '關閉後學生無法繼續儲存或提交，已提交作答會保留。確定關閉？')) return
  busy.value = true; error.value = ''
  try { assignment.value = await api(`/assignments/${assignment.value.id}/${target}`, { method: 'POST' }); editing.value = false; notice.value = target === 'publish' ? '測驗已發布。' : '測驗已關閉。' } catch (e) { error.value = e.message } finally { busy.value = false }
}
async function startQuiz(){busy.value=true;error.value='';try{await api(`/assignments/${assignment.value.id}/start`,{method:'POST'});await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(submit) {
  if (!canWrite.value || busy.value) return
  if (submit && assignment.value.questions.some(q => (q.questionType==='essay'||!q.questionType) && !answers.value[q.id]?.trim())) { error.value = '提交前請完成每一道題目。草稿可以保留未完成內容。'; return }
  if (submit) { const policy = assignment.value.allowRevisions ? '確定提交新版本？將保留歷史內容，且新版本須重新評分。' : '提交後不可修改，請確認所有作答。確定提交？'; if (!window.confirm(policy)) return }
  busy.value = true; error.value = ''; notice.value = ''
  try { acceptSubmission(await api(`/assignments/${assignment.value.id}/my-submission`, { method: 'POST', body: { expectedVersion: own.value.version, submit, answers: assignment.value.questions.map(q => ({ questionId: q.id, text: answers.value[q.id] || '' })) } })); notice.value = submit ? (assignment.value.isPractice ? '練習作答已提交，不計入正式學生紀錄。' : '作答已成功提交，教師與助教現在可以查看。') : '草稿已儲存至資料庫。' } catch (e) { error.value = e.message } finally { busy.value = false }
}
async function openReview(submissionId) { busy.value = true; error.value = ''; try { review.value = await api(`/assignments/${assignment.value.id}/submissions/${submissionId}`) } catch (e) { error.value = e.message } finally { busy.value = false } }
async function refreshRoster() { try { submitted.value = await api(`/assignments/${assignment.value.id}/submissions`) } catch(e) { error.value = e.message } }
function guard() { return !(dirty.value || editing.value) || window.confirm('目前有尚未儲存的編輯，確定離開？') }
onBeforeRouteLeave(guard)
onBeforeRouteUpdate(async () => { if (!guard()) return false; assignment.value = null; own.value = null; answers.value = {}; return true })
function beforeUnload(event) { if (dirty.value || editing.value) { event.preventDefault(); event.returnValue = '' } }
window.addEventListener('beforeunload', beforeUnload)
onBeforeUnmount(() => { clearInterval(timer); window.removeEventListener('beforeunload', beforeUnload) })
function answerFor(submission, questionId) { return submission?.answers.find(a => a.questionId === questionId) }
function displayAnswer(question,text){if(!question.questionType || question.questionType==='essay')return text;try{return JSON.parse(text || '[]').map(n=>question.options[n]).join('、')}catch{return text}}
</script>
<template><RouterLink :to="assignment ? `/courses/${assignment.courseId}?section=assessments` : '/assessments'" class="back-link"><ArrowLeft :size="15" />返回課程測驗</RouterLink><p v-if="error" class="error-box" role="alert">{{ error }}<button class="text-button" @click="reload">重新載入</button></p><p v-if="notice" class="success-box" role="status"><CheckCircle2 :size="16" />{{ notice }}</p><p v-if="loading" class="empty-inline">載入測驗中…</p><template v-if="assignment && !loading"><section class="page-heading"><div><p class="eyebrow">{{ assignment.courseTitle }} · ONLINE QUIZ</p><h1>{{ assignment.title }}</h1><p class="muted">{{ assignment.questions.length }} 道題目 · 個人作答</p></div><span class="assignment-status" :class="assignment.status">{{ assignmentStatus[assignment.status] }}</span></section><nav class="course-navigation" aria-label="測驗功能"><a href="#assignment-content">作答與評閱</a><a href="#assignment-discussions">提問（公開設定）</a></nav><section id="assignment-content" class="assignment-meta surface"><span><CalendarDays :size="16" /><b>開放</b>{{ formatDate(assignment.opensAt) }}</span><span><CalendarDays :size="16" /><b>截止</b>{{ formatDate(assignment.dueAt) }}</span><span v-if="own" class="submission-status" :class="own.status">{{ submissionStatus[own.status] }}</span></section>
  <div v-if="staff" class="staff-actions"><p class="muted">{{ assignment.status === 'draft' ? '草稿僅課程教師與助教可見。發布前請確認題目與時間。' : '已發布題目已鎖定。學生提交後，可在下方查看內容。' }}</p><div><button v-if="assignment.status === 'draft'" class="button secondary" :disabled="busy" @click="editing = !editing"><Pencil :size="15" />編輯草稿</button><button v-if="assignment.status === 'draft' && !editing" class="button primary" :disabled="busy || assignment.courseStatus === 'archived'" @click="transition('publish')"><Send :size="15" />發布測驗</button><button v-if="assignment.status === 'published'" class="button secondary" :disabled="busy" @click="transition('close')"><LockKeyhole :size="15" />關閉測驗</button></div></div>
  <section v-if="!staff && assignment.learningGate?.locked" class="surface form-surface"><h2>測驗前教材學習門檻</h2><p>請先完成下列教材的有效閱讀／觀看時間，再開始測驗。影片依內容時間計算（2倍速實看10分鐘計20分鐘），講義依實際閱讀時間；快轉跳過不計。</p><article v-for="r in assignment.learningGate.requirements" :key="r.resourceId" class="question-editor"><RouterLink :to="`/courses/${assignment.courseId}/materials/${r.resourceId}`">{{r.title}}</RouterLink><p>已累積 {{r.accumulatedSeconds}} 秒／要求 {{r.minimumSeconds}} 秒 · {{r.met?'已達標':'尚差 '+Math.max(0,r.minimumSeconds-r.accumulatedSeconds)+' 秒'}}</p></article><button class="button secondary" :disabled="busy" @click="reload">更新學習進度</button><button class="button primary" :disabled="busy || !assignment.learningGate.met || assignment.status!=='published' || assignment.courseStatus==='archived'" @click="startQuiz">開始測驗</button></section><QuizScoringPlan v-if="assignment.isQuiz && !editing && (staff || !assignment.learningGate?.locked)" :max-score="assignment.maxScore" :questions="assignment.questions" />
  <AssignmentEditor v-if="editing" :quiz="assignment.isQuiz" :initial="assignment" :busy="busy" @save="saveAssignment" @cancel="editing = false" />
  <section v-if="assignment.instructions" class="surface assignment-instructions"><h2>測驗說明與案例資料</h2><p>{{ assignment.instructions }}</p></section>
  <p v-if="!staff && restriction" class="submission-notice"><LockKeyhole :size="17" />{{ restriction }}</p>
  <section v-for="question in assignment.questions" :key="question.id" class="surface assignment-question"><header><span class="question-number">{{ String(question.sortOrder).padStart(2, '0') }}</span><div><h2>題目 {{ question.sortOrder }}</h2></div></header><p class="question-prompt">{{ question.promptText }}</p><p v-if="assignment.isQuiz" class="field-hint">{{question.points!=null?'配分：'+question.points:'未指定配分，依測驗滿分自動均分'}} · {{question.questionType==='essay'?'教師評分':'系統自動批改；多選須完全答對'}}</p><p v-if="staff && question.questionType!=='essay'" class="field-hint">標準答案：{{ question.standardAnswer?.map(n=>question.options[n]).join('、') }}</p><template v-if="!staff && own"><label v-if="own.status !== 'submitted' || assignment.allowRevisions" :for="`answer-${question.id}`" class="answer-label">題目 {{ question.sortOrder }} 作答<QuestionAnswer :question="question" v-model="answers[question.id]" :disabled="busy || !canWrite" /><span class="char-count">{{ (answers[question.id] || '').length }} / 16,000</span></label><div v-else class="submitted-answer"><h3>你的作答</h3><p>{{ displayAnswer(question,answerFor(own, question.id)?.text) || '尚未儲存作答。' }}</p></div><details v-if="answerFor(own, question.id)?.revisions.length" class="revision-history"><summary><History :size="14" />已儲存版本（{{ answerFor(own, question.id).revisions.length }}）</summary><article v-for="revision in answerFor(own, question.id).revisions" :key="revision.id"><header><strong>版本 {{ revision.revisionNo }}</strong><time>{{ formatDate(revision.createdAt) }}</time><span v-if="revision.isSubmitted" class="status-badge">提交版本</span></header><p>{{ displayAnswer(question,revision.text) || '（空白草稿）' }}</p></article></details></template></section>
  <section v-if="!staff && own && (own.status !== 'submitted' || assignment.allowRevisions)" class="submission-actions surface"><div><strong>{{ dirty ? '有尚未儲存的修改' : own.status === 'submitted' ? '目前提交版本已保存' : own.id ? '目前草稿已儲存' : '尚未儲存作答' }}</strong><p v-if="assignment.isPractice" class="field-hint">學生體驗模式：提交自己的練習作答，不納入正式學生紀錄。切回教學視角可從獨立練習紀錄評分。</p><p v-else>{{ assignment.allowRevisions ? '可於截止前提交新版本；歷史與原版本成績保留。已提交後的修訂請直接提交新版本。' : '草稿可繼續修改；提交後本次作答將鎖定。' }}截止時間以伺服器判定。</p></div><div><button v-if="own.status !== 'submitted'" class="button secondary" :disabled="busy || !canWrite || !dirty" @click="save(false)"><Save :size="16" />{{ busy ? '處理中…' : '儲存草稿' }}</button><button class="button primary" :disabled="busy || !canWrite" @click="save(true)"><Send :size="16" />提交給教師／助教</button></div></section>
  <section v-if="staff" class="surface submission-roster"><div class="table-toolbar"><div><h2>已提交作答 <span class="count-pill">{{ submitted.length }}</span></h2><p class="muted">只顯示已完成提交的個人作答，不包含學生草稿。</p></div><button class="button secondary" :disabled="busy" @click="reload"><RefreshCw :size="15" />重新整理</button></div><div v-if="submitted.length" class="table-scroll"><table class="data-table"><thead><tr><th scope="col">學生</th><th scope="col">提交時間</th><th scope="col">作答題數</th><th scope="col">最新版本評分</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="submission in submitted" :key="submission.id"><td>{{ submission.studentName }}</td><td>{{ formatDate(submission.submittedAt) }}</td><td>{{ submission.answerCount }}</td><td>{{ {ungraded:"待評分",pending_essay:"申論題待評分",auto_scored:"已自動評分，待發布",draft:"評分草稿",released:"已發布"}[submission.gradingStatus] }}</td><td><button class="button secondary" :disabled="busy" @click="openReview(submission.id)"><Eye :size="15" />查看作答</button></td></tr></tbody></table></div><p v-else class="empty-inline">目前尚無學生提交作答。</p></section>
  <section v-if="staff && review" class="surface submitted-review"><div class="section-title"><div><p class="eyebrow">SUBMITTED WORK</p><h2>{{ review.studentName }} · 提交紀錄</h2><p>提交時間 {{ formatDate(review.submittedAt) }}</p></div><button class="icon-button" aria-label="關閉作答檢視" @click="review = null"><X :size="18" /></button></div></section>
  <TeachingPanel v-if="!staff && own?.id" :key="`${own.id}-${own.version}`" :assignment="assignment" :submission-id="own.id" :staff="false" /><TeachingPanel v-if="staff && review" :key="review.id" :assignment="assignment" :submission-id="review.id" :staff="true" @changed="refreshRoster" /><section id="assignment-discussions"><h2>提問</h2><DiscussionPanel :assignment-id="assignment.id" :staff="staff" :practice="assignment.isPractice" /></section><RouterLink v-if="assignment.isQuiz" :to="`/courses/${assignment.courseId}?section=grades`" class="button secondary">查看測驗／作業成績管理</RouterLink><p class="page-note">客觀題由系統自動批改，多選採全對得分；申論題由教師／助教評閱。正式成績發布後可見。</p>
</template></template>
